const token = getToken();
  const categoryId = getCategoryId();

  await spec()
 .put(`/api/editCategory/${categoryId}`)
 .withHeaders('authorization', token)
 .withJson({

   name: 'Categoria Editada Automático',
   description: 'Categoria atualizada via teste automático'
 })
 .expectStatus(200)
 .expectJsonLike({
   success: true
 });

